  extends JSX.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof bubbleVariants> {
  class?: string;
}

interface BubbleContentProps extends JSX.HTMLAttributes<HTMLDivElement> {
  class?: string;
}

interface BubbleReactionsProps extends JSX.HTMLAttributes<HTMLDivElement> {
